38	    /// Visit a non-source snippet to track value references
39	    pub(crate) fn visit_non_source_snippet(&mut self, root: &AnyJsRoot) {
40	        let preorder = root.syntax().preorder();
41	
42	        for event in preorder {
43	            match event {
44	                WalkEvent::Enter(node) => {
45	                    if let Some(reference) = JsxReferenceIdentifier::cast_ref(&node) {
46	                        self.visit_jsx_reference_identifier(reference);
47	                    } else if let Some(reference) = JsReferenceIdentifier::cast_ref(&node) {
48	                        self.visit_reference_identifier(reference);
49	                    } else if let Some(member) = JsStaticMemberExpression::cast_ref(&node) {
50	                        self.visit_static_member_expression(member);
51	                    }
52	                }
53	                WalkEvent::Leave(_) => {}
54	            }
55	        }
56	    }
57	
58	    /// Visit an HTML root to track component element names as value references.
59	    ///
60	    /// This extracts component names from Vue/Svelte templates like:
61	    /// - `<Component />` → tracks `Component`
62	    /// - `<AvatarPrimitive.Fallback>` → tracks `AvatarPrimitive`
63	    pub(crate) fn visit_html_root(&mut self, root: &HtmlRoot) {
64	        for node in root.syntax().descendants() {
65	            // Check HtmlElement: <Component>...</Component>
66	            if let Some(element) = HtmlElement::cast_ref(&node) {
67	                self.visit_html_element(&element);
68	            }
69	
70	            // Check HtmlSelfClosingElement: <Component />
71	            if let Some(element) = HtmlSelfClosingElement::cast_ref(&node) {
72	                self.visit_html_self_closing_element(&element);
73	            }
74	        }
75	    }
76	
77	    fn visit_html_element(&mut self, element: &HtmlElement) -> Option<()> {
78	        // Skip script and style tags - these are not component references
79	        if element.is_script_tag() || element.is_style_tag() {
80	            return None;
81	        }
82	
83	        let opening = element.opening_element().ok()?;
84	        let name = opening.name().ok()?;
85	
86	        self.track_component_reference(&name);
87	
88	        Some(())
89	    }
90	
91	    fn visit_html_self_closing_element(&mut self, element: &HtmlSelfClosingElement) -> Option<()> {
92	        let name = element.name().ok()?;
93	
94	        self.track_component_reference(&name);
95	
96	        Some(())
97	    }
98	
99	    /// Track a component name as a value reference
100	    fn track_component_reference(&mut self, name: &AnyHtmlTagName) {
101	        match name {
102	            AnyHtmlTagName::HtmlComponentName(component) => {
103	                // Track simple component: <Component>
104	                if let Ok(token) = component.value_token() {
105	                    self.references
106	                        .insert(token.text_trimmed_range(), token.token_text_trimmed());
107	                }
108	            }
109	            AnyHtmlTagName::HtmlMemberName(member) => {
110	                // Track the base component from member expression: <Component.Member>
111	                if let Ok(object) = member.object() {
112	                    self.track_component_object(&object);
113	                }
114	            }
115	            AnyHtmlTagName::HtmlTagName(_) => {
116	                // Regular HTML tag, don't track
117	            }
118	        }
119	    }
120	
121	    /// Track the object part of a member expression
122	    fn track_component_object(&mut self, object: &AnyHtmlComponentObjectName) {
123	        match object {
124	            AnyHtmlComponentObjectName::HtmlTagName(tag) => {
125	                // For member expressions starting with lowercase (unusual but possible)
126	                if let Ok(token) = tag.value_token() {
127	                    self.references
128	                        .insert(token.text_trimmed_range(), token.token_text_trimmed());
129	                }
130	            }
131	            AnyHtmlComponentObjectName::HtmlComponentName(component) => {
132	                // Track the component name
133	                if let Ok(token) = component.value_token() {
134	                    self.references
135	                        .insert(token.text_trimmed_range(), token.token_text_trimmed());
136	                }
137	            }
138	            AnyHtmlComponentObjectName::HtmlMemberName(member) => {
139	                // Nested member - track its object recursively
140	                // e.g., A.B.C - track A
141	                if let Ok(object) = member.object() {
142	                    self.track_component_object(&object);
143	                }
144	            }
145	        }
146	    }
147	
148	    fn visit_jsx_reference_identifier(&mut self, reference: JsxReferenceIdentifier) -> Option<()> {
149	        let name_token = reference.value_token().ok()?;
150	        self.references.insert(
151	            name_token.text_trimmed_range(),
152	            name_token.token_text_trimmed(),
153	        );
154	        Some(())
155	    }
156	
157	    fn visit_reference_identifier(&mut self, reference: JsReferenceIdentifier) -> Option<()> {
158	        let usage = AnyJsIdentifierUsage::from(reference.clone());
159	        if usage.is_only_type() {
160	            return None;
161	        }
162	        let name_token = reference.value_token().ok()?;
163	        self.references.insert(
164	            name_token.text_trimmed_range(),
165	            name_token.token_text_trimmed(),
166	        );
167	        Some(())
168	    }
169	
170	    fn visit_static_member_expression(&mut self, member: JsStaticMemberExpression) -> Option<()> {
171	        let object = member.object().ok()?;
172	        if let Some(reference) = object.as_js_reference_identifier() {
173	            self.visit_reference_identifier(reference.clone())?;
174	        }
175	        Some(())
176	    }
177	}
